<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Sasta Coder AI Hub - All-in-One</title>
    <script src="https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4"></script>
</head>
<body class="bg-slate-950 text-slate-100 flex flex-col h-screen p-4 max-w-md mx-auto">
    <header class="flex justify-between items-center border-b border-slate-800 pb-3 mb-3">
        <h1 class="text-lg font-bold text-cyan-400">⚡ HopWeb AI Hub</h1>
        <select id="modelSelect" class="bg-slate-900 border border-slate-700 text-xs rounded px-2 py-1 text-slate-300">
            <option value="gpt-4o-mini">GPT-4o Mini</option>
            <option value="claude-3-haiku">Claude 3 Haiku</option>
            <option value="gemini-flash">Gemini Flash</option>
        </select>
    </header>

    <div id="chatBox" class="flex-1 overflow-y-auto space-y-3 pr-1 mb-3 text-sm">
        <div class="bg-slate-900 p-3 rounded-xl max-w-[85%] text-slate-300">Arey bhai! HopWeb me chal raha hai. Model select karo aur message bhejo!</div>
    </div>

    <form id="chatForm" class="flex gap-2 bg-slate-900 p-2 rounded-xl border border-slate-800">
        <input type="text" id="userInput" placeholder="Type a message..." class="flex-1 bg-transparent px-2 py-1 text-sm text-slate-100 focus:outline-none" required>
        <button type="submit" class="bg-cyan-600 hover:bg-cyan-500 text-white px-3 py-1.5 rounded-lg text-sm font-medium">Send</button>
    </form>

    <script>
        const chatBox = document.getElementById('chatBox');
        const chatForm = document.getElementById('chatForm');
        const userInput = document.getElementById('userInput');
        const modelSelect = document.getElementById('modelSelect');

        chatForm.onsubmit = async (e) => {
            e.preventDefault();
            const text = userInput.value;
            const model = modelSelect.value;

            chatBox.innerHTML += `<div class="bg-cyan-950/60 p-3 rounded-xl max-w-[85%] ml-auto text-cyan-200">${text}</div>`;
            userInput.value = '';
            chatBox.scrollTop = chatBox.scrollHeight;

            try {
                // Using Pollinations public endpoint as a robust fallback for mobile previewing
                const res = await fetch(`https://text.pollinations.ai/${encodeURIComponent(text)}?model=${model}`);
                const reply = await res.text();
                chatBox.innerHTML += `<div class="bg-slate-900 p-3 rounded-xl max-w-[85%] text-slate-300">${reply}</div>`;
            } catch (err) {
                chatBox.innerHTML += `<div class="bg-red-950/50 p-3 rounded-xl max-w-[85%] text-red-300">Error: Failed to fetch response.</div>`;
            }
            chatBox.scrollTop = chatBox.scrollHeight;
        };
    </script>
</body>
</html>
